sys_script_include.script:
function GetInstanceAIStatus()
{
	aistatus = {};

	aistatus.now_assist_agents_installation = {};
	aistatus.now_assist_agents_installation.title = 'ServiceNow Otto AI Agents (Now Assist AI Agents) Store App';
	aistatus.now_assist_agents_installation.type = 'boolean';
	aistatus.now_assist_agents_installation.status = IsNowAssistAIAgentsInstalled();
	aistatus.now_assist_agents_installation.info = 'Checks if the required Store App is installed to use AI Agents. If the "ServiceNow Otto AI Agents" (formerly "Now Assist AI Agents") Store App can only be installed as a dependency, installing the "Now Assist for Creator" (sn_now_creator) Store App is an option. You may have to sync the store before the Store App can be found.';
	aistatus.now_assist_agents_installation.config_url =
		GetInstanceUrl() + GetAppManagerPath('sn_aia');



	aistatus.ai_search = {};
	aistatus.ai_search.title = 'AI Search';
	aistatus.ai_search.type = 'boolean';
	aistatus.ai_search.info = 'Checks if AI Search is provisioned on the instance.';
	aistatus.ai_search.config_url = GetInstanceUrl() + 'now/nav/ui/classic/params/target/ais_status.do';
	aistatus.ai_search.documentation_url = 'https://support.servicenow.com/kb?id=kb_article_view&sysparm_article=KB0867751';
	var diagnostics = GetDiagnostics();
	aistatus.ai_search.status = GetBoolValue(GetValue(diagnostics,'ais.status','ais.enabled'));


	aistatus.now_assist_creator_installation = {};
	aistatus.now_assist_creator_installation.title = 'ServiceNow Otto for Creator (Now Assist for Creator) Store App';
	aistatus.now_assist_creator_installation.type = 'boolean';
	aistatus.now_assist_creator_installation.status = IsStoreAppInstalled('sn_now_creator');
	aistatus.now_assist_creator_installation.info = 'Checks if the "ServiceNow Otto for Creator" Store App is installed. You may have to sync the store before the Store App can be found.';
	aistatus.now_assist_creator_installation.config_url = 
		GetInstanceUrl() + GetAppManagerPath('sn_now_creator');


	aistatus.now_assist_panel = {};
	aistatus.now_assist_panel.title = 'ServiceNow Otto panel (Now Assist Panel)';
	aistatus.now_assist_panel.type = 'boolean';
	aistatus.now_assist_panel.status = false;
	aistatus.now_assist_panel.info = 'Checks if the ServiceNow Otto panel (formerly Now Assist Panel) is "turned on" on. If no Plugin is installed yet, installing the "ServiceNow Otto for Creator" (formerly "Now Assist for Creator") (sn_now_creator) is an option.';
	aistatus.now_assist_panel.config_url = GetInstanceUrl() +'now/now-assist-admin/now-assist-panel';
	var grNAS = new GlideRecord('sn_nowassist_settings');
	grNAS.addQuery('type','=','nap');
	grNAS.addQuery('name','=','Now Assist Panel Settings');
	grNAS.addQuery('active','=',true);
	grNAS.query();
	while (grNAS.next())
	{
		var variables = GetVariablesFromRecord(grNAS);
		if (GetValue(variables,'nap_enabled','value') == 1)
		{
			aistatus.now_assist_panel.status = true;
		}
	}


	var strPanelName = '';
	if (IsValidTable('sys_now_assist_deployment') == true)
	{
		var strPanelName = 'Now Assist Panel - Platform (default)';
		var grNAD = new GlideRecord('sys_now_assist_deployment');
		grNAD.addQuery('assistant_type','=','nap');
		grNAD.addQuery('name','=',strPanelName);
		grNAD.query();
		if (grNAD.next() != true)
		{
			strPanelName = 'ServiceNow Otto panel - Platform (default)';
			var grNAD = new GlideRecord('sys_now_assist_deployment');
			grNAD.addQuery('assistant_type','=','nap');
			grNAD.addQuery('name','=',strPanelName);
			grNAD.query();
			if (grNAD.next() != true)
			{
				strPanelName = '';
			}
		}
	}

	aistatus.now_assist_panel_platform = {};
	if (strPanelName == '')
	{
		aistatus.now_assist_panel_platform.title = 'Platform (default) Panel Activation';
		aistatus.now_assist_panel_platform.type = 'boolean';
		aistatus.now_assist_panel_platform.status = false;
		aistatus.now_assist_panel_platform.info = 'Checks if a Platform default panel is active.';
	}
	else
	{
		aistatus.now_assist_panel_platform.title = strPanelName + ' Activation';
		aistatus.now_assist_panel_platform.type = 'boolean';
		aistatus.now_assist_panel_platform.status = false;
		aistatus.now_assist_panel_platform.info = 'Checks if the panel "'+strPanelName+'" is active.';
		aistatus.now_assist_panel_platform.config_url = GetInstanceUrl()+'now/conversational-studio/assistants/all';
		if (IsValidTable('sys_now_assist_deployment') == true)
		{
			var grNAD = new GlideRecord('sys_now_assist_deployment');
			grNAD.addQuery('active','=','true');
			grNAD.addQuery('assistant_type','=','nap');
			grNAD.addQuery('name','=',strPanelName);
			grNAD.query();
			while (grNAD.next() == true)
			{
				aistatus.now_assist_panel_platform.status = true;
			}
		}
	}



	aistatus.now_assist_panel_platform_deployment = {};
	aistatus.now_assist_panel_platform_deployment.title = 'Now Assist Panel Deployment Channel';
	aistatus.now_assist_panel_platform_deployment.type = 'boolean';
	aistatus.now_assist_panel_platform_deployment.status = false;
	aistatus.now_assist_panel_platform_deployment.info = 'Checks if the Now Assist Panel Deployment Channel is configured for "'+strPanelName+'". Navigate to "Assistant Designer" -> "'+strPanelName+'" -> "Edit" -> "Settings" -> "Display experiences".';
	aistatus.now_assist_panel_platform_deployment.config_url =
		GetInstanceUrl()+'now/conversational-studio/assistants/all';
	if (IsValidTable('sys_now_assist_deployment_channel') == true)
	{
		var grNAPDC = new GlideRecord('sys_now_assist_deployment_channel');
		grNAPDC.addQuery('active','=','true');
		grNAPDC.addQuery('config_type','=','');
		grNAPDC.addQuery('document_table','=','sys_ux_app');
		grNAPDC.addQuery('experience','=','self_service_dialog'); 
		grNAPDC.query();
		while (grNAPDC.next() == true)
		{
			if (grNAPDC.now_assist_deployment.getDisplayValue() == strPanelName)
			{
				aistatus.now_assist_panel_platform_deployment.status = true;
			}	
		}
	}



	aistatus.now_assist_ignore_fulfiller_subscription_check = {};
	aistatus.now_assist_ignore_fulfiller_subscription_check.title = 'Ignore Fulfiller Subscription Check';
	var strPropName = 'sn_nowassist_admin.ignoreFulfillerSubscriptionCheck';
	aistatus.now_assist_ignore_fulfiller_subscription_check.type = 'boolean';
	aistatus.now_assist_ignore_fulfiller_subscription_check.status = 
		GetBoolValue(
			GetProperty(strPropName));
	aistatus.now_assist_ignore_fulfiller_subscription_check.info = 
		'Checks if the system property "' + strPropName + '" is set to "true". Setting this system property is documented as a fix to PRB1965167.';

	var grProp = GetPropertyRecord(strPropName);
	var strUrl = '';
	if (IsValidRecord(grProp) == true)
	{
		strUrl = GetInstanceRecordUrl('sys_properties',grProp.sys_id);
	}
	else
	{
		strUrl = GetInstanceListUrl('sys_properties','','name='+strPropName,0);
	}
	aistatus.now_assist_ignore_fulfiller_subscription_check.config_url = strUrl;


	var strLLMGatewayUrl = 'https://llmgateway-dart-default-dart001.aus100.service-now.com';

	aistatus.llmgateway_service = {};
	aistatus.llmgateway_service.title = 'LLM Gateway Service';
	aistatus.llmgateway_service.info = 
		'The LLMGateway related sys_service_endpoint records should point to: "'+strLLMGatewayUrl+'". Unfortunately the status cannot be determined unless the user is maint. Follow instructions in KB3084849 to fix this.';
	var aLLMServices = ['LLMGateway','LLMProxy','MLPredictor-Triton'];
	var strEncodedQuery = 'nameIN' + GetStringValue(aLLMServices);
	if (IsUserMaint())
	{
		var aServicesSysIds = [];
		var grSS = new GlideRecord('sys_service');
		grSS.addEncodedQuery(strEncodedQuery);
		grSS.query();
		while (grSS.next() == true)
		{
			aServicesSysIds.push(GetStringValue(grSS.sys_id));
		}

		aistatus.llmgateway_service.type = 'boolean';
		aistatus.llmgateway_service.status = true;
		var grSSE = new GlideRecord('sys_service_endpoint');
		//grSSE.addQuery('url','=','https://llmgateway-dart');
		grSSE.addQuery('service','IN',GetStringValue(aServicesSysIds));
		grSSE.query();
		while (grSSE.next() == true)
		{
			if (IsValidUrl(grSSE.url) == false)
			{
				aistatus.llmgateway_service.status = false;
			}
			else if (grSSE.url == 'https://llmgateway-dart')
			{
				aistatus.llmgateway_service.status = false;
			}
		}
	}
	aistatus.llmgateway_service.config_url = GetInstanceListUrl('sys_service','',strEncodedQuery);



	aistatus.llmgateway_connection = {};
	aistatus.llmgateway_connection.title = 'LLM Gateway Connection';
	aistatus.llmgateway_connection.type = 'boolean';
	var grConnection = new GlideRecord('http_connection');
	grConnection.addQuery('name','=','Now LLM');
	grConnection.query();
	var bStatus = false;
	if (grConnection.getRowCount() == 1)
	{
		if (grConnection.next())
		{
			aistatus.llmgateway_connection.config_url = GetInstanceRecordUrl('http_connection',grConnection.sys_id);
			var strConnectionUrl = GetStringValue(grConnection.connection_url);
			if (strConnectionUrl == strLLMGatewayUrl)
			{
				bStatus = true;
			}
		}
	}
	aistatus.llmgateway_connection.status = bStatus;
	aistatus.llmgateway_connection.info =
		'The HTTP Connection record "Now LLM" should point to "'+strLLMGatewayUrl + '". Follow instructions in KB3084849 to fix this.';



	aistatus.license_tier = {};
	// https://support.servicenow.com/kb?id=kb_article_view&sysparm_article=KB2975850
	aistatus.license_tier.title = 'Prime License Tier';
	aistatus.license_tier.type = 'boolean';
	aistatus.license_tier.status = IsPrimeTierLicenseAvailable();
	aistatus.license_tier.info = 
		'Checks if the instance has the "prime" license tier - which is required to build and run custom AI agents. One option to enable the Prime License Tier is to install the "App Engine - Prime" Store App.';
	aistatus.license_tier.config_url =
		GetInstanceUrl()
		+ GetAppManagerPath('sn_aeai_prime');


	// Beancounting

	if (IsValidTable('sys_now_assist_deployment') == true)
	{
		aistatus.now_assist_deployments = {};
		aistatus.now_assist_deployments.title = 'Now Assist Deployments';
		aistatus.now_assist_deployments.type = 'count';
		aistatus.now_assist_deployments.info = 'The number of ACTIVE Now Assist Deployments.';
		aistatus.now_assist_deployments.config_url = GetInstanceListUrl('sys_now_assist_deployment','','active=true');
		var grNAD = new GlideRecord('sys_now_assist_deployment');
		grNAD.addQuery('active','=','true');
		grNAD.query();
		aistatus.now_assist_deployments.status = grNAD.getRowCount();
	}


	if (IsValidTable('sn_aia_team') == true)
	{
		aistatus.agentic_workflows = {};
		aistatus.agentic_workflows.title = 'Agentic Workflows';
		aistatus.agentic_workflows.type = 'count';
		var grWorkflows = new GlideRecord('sn_aia_team');
		grWorkflows.query();
		aistatus.agentic_workflows.status = grWorkflows.getRowCount();
		aistatus.agentic_workflows.info = 
			'The number of Agentic Workflows available on this instance.';
		aistatus.agentic_workflows.config_url = GetInstanceListUrl('sn_aia_team');
	}

	if (IsValidTable('sn_aia_agent_config') == true)
	{	
		aistatus.ai_agents = {};
		aistatus.ai_agents.title = 'AI Agents';
		aistatus.ai_agents.type = 'count';
		var grAgents = new GlideRecord('sn_aia_agent_config');
		grAgents.addActiveQuery();
		grAgents.query();
		aistatus.ai_agents.status = grAgents.getRowCount();
		aistatus.ai_agents.info = 
			'The number of ACTIVE AI Agent Configs available on this instance.';
		aistatus.ai_agents.config_url =
			GetInstanceListUrl('sn_aia_agent_config','','active=true');	
	}

	if (IsValidTable('sys_one_extend_capability') == true)
	{
		aistatus.ai_skills = {};
		aistatus.ai_skills.title = 'AI Skills';
		aistatus.ai_skills.type = 'count';
		var grSkills = new GlideRecord('sys_one_extend_capability');
		grSkills.addActiveQuery();
		grSkills.addQuery('type','=','skill');
		grSkills.query();
		aistatus.ai_skills.status = grSkills.getRowCount();
		aistatus.ai_skills.info = 
			'The number of ACTIVE AI Skills available on this instance.';
		aistatus.ai_skills.config_url =
			GetInstanceListUrl('sys_one_extend_capability','','active=true^type=skill');		
	}

	if (IsValidTable('sys_one_extend_definition_config') == true)
	{
		aistatus.one_extend_definition_config = {};
		aistatus.one_extend_definition_config.title = 'OneExtend Definition Configs';
		aistatus.one_extend_definition_config.type = 'count';
		var grOEDC = new GlideRecord('sys_one_extend_definition_config');
		grOEDC.addActiveQuery();
		grOEDC.query();
		aistatus.one_extend_definition_config.status = grOEDC.getRowCount();
		aistatus.one_extend_definition_config.info = 
			'The number of ACTIVE OneExtend Definition Config records on this instance. These records "bind" skills to LLM Configurations.';
		aistatus.one_extend_definition_config.config_url =
			GetInstanceListUrl('sys_one_extend_definition_config','','active=true');		
	}

	return aistatus;
}
